use smaul_native::data_filter::filter_record;
use smaul_native::synthetic_data;
use rand::SeedableRng;
use serde_json::Value;
use std::fs::{self,File};
use std::io::{self,BufRead,BufReader,Write};
use std::path::{Path,PathBuf};
use std::process::Command;

fn val(a:&[String],name:&str,default:&str)->String{a.windows(2).find(|x|x[0]==name).map(|x|x[1].clone()).unwrap_or_else(||default.into())}
fn text(v:&Value)->Option<String>{match v{Value::String(s)=>Some(s.clone()),Value::Object(o)=>{let m=o.iter().map(|(k,v)|(k.to_ascii_lowercase(),v)).collect::<std::collections::HashMap<_,_>>();if let(Some(a),Some(b))=(m.get("prompt").and_then(|v|v.as_str()),m.get("completion").and_then(|v|v.as_str())){return Some(format!("{a}\n{b}"))}for k in ["text","content","document","body","code","prompt","completion"]{if let Some(s)=m.get(k).and_then(|v|v.as_str()).filter(|x|!x.trim().is_empty()){return Some(s.into())}}m.values().filter_map(|v|v.as_str()).max_by_key(|x|x.len()).map(str::to_owned)},Value::Array(a)=>{let x=a.iter().filter_map(text).collect::<Vec<_>>();(!x.is_empty()).then(||x.join("\n"))},_=>None}}
fn stream_jsonl(path:&Path,dataset:&str,min:usize,max:usize,limit:usize,mut out:impl Write)->Result<usize,String>{let r=BufReader::new(File::open(path).map_err(|e|e.to_string())?);let mut n=0;for line in r.lines(){let line=line.map_err(|e|e.to_string())?;let Ok(v)=serde_json::from_str::<Value>(&line)else{continue};if let Some(t)=filter_record(&v,dataset,min,max){writeln!(out,"{}",serde_json::json!({"text":t})).map_err(|e|e.to_string())?;n+=1;if limit>0&&n>=limit{break}}}Ok(n)}
fn filter_stdin(dataset:&str,min:usize,max:usize)->Result<(),String>{let stdin=io::stdin();let mut out=io::BufWriter::new(io::stdout());for line in stdin.lock().lines(){let line=line.map_err(|e|e.to_string())?;let Ok(v)=serde_json::from_str::<Value>(&line)else{continue};if let Some(t)=filter_record(&v,dataset,min,max){writeln!(out,"{}",serde_json::json!({"text":t})).map_err(|e|e.to_string())?}}Ok(())}
fn synthetic(count:usize,out:&Path,seed:u64)->Result<(),String>{let mut rng=rand::rngs::StdRng::seed_from_u64(seed);let mut f=io::BufWriter::new(File::create(out).map_err(|e|e.to_string())?);for _ in 0..count{serde_json::to_writer(&mut f,&synthetic_data::generate(&mut rng)).map_err(|e|e.to_string())?;f.write_all(b"\n").map_err(|e|e.to_string())?}Ok(())}
fn download(repo:&str,path:&str,out:&Path)->Result<(),String>{let api=format!("https://huggingface.co/api/datasets/{repo}/tree/main/{path}?recursive=true&expand=false&limit=1000");let body=String::from_utf8(Command::new("curl").args(["-fsSL",&api]).output().map_err(|e|e.to_string())?.stdout).map_err(|e|e.to_string())?;let items:Vec<Value>=serde_json::from_str(&body).map_err(|e|e.to_string())?;let files=items.iter().filter_map(|x|x.get("path").and_then(|v|v.as_str())).filter(|x|x.ends_with(".parquet")).collect::<Vec<_>>();if files.is_empty(){return Err(format!("no parquet files found in {repo}/{path}"))}for rel in files{let target=out.join(rel.rsplit('/').next().unwrap_or("data.parquet"));if target.exists(){continue}if let Some(parent)=target.parent(){fs::create_dir_all(parent).map_err(|e|e.to_string())?}let url=format!("https://huggingface.co/datasets/{repo}/resolve/main/{rel}");let status=Command::new("curl").args(["-fL","--retry","5","-o",target.to_str().unwrap_or("data.parquet"),&url]).status().map_err(|e|e.to_string())?;if !status.success(){return Err(format!("download failed: {rel}"))}}Ok(())}
fn main()->Result<(),String>{let a=std::env::args().collect::<Vec<_>>();let command=a.get(1).map(String::as_str).unwrap_or("help");match command{"filter"=>{filter_stdin(&val(&a,"--dataset","auto"),val(&a,"--min-chars","20").parse().unwrap(),val(&a,"--max-chars","1000000").parse().unwrap())},"stream"=>{let input=PathBuf::from(val(&a,"--input","./datasets/train.jsonl"));let dataset=val(&a,"--dataset","auto");let min=val(&a,"--min-chars","20").parse().unwrap();let max=val(&a,"--max-chars","1000000").parse().unwrap();let limit=val(&a,"--max-records","0").parse().unwrap();let n=stream_jsonl(&input,&dataset,min,max,limit,io::stdout())?;eprintln!("[DONE] streamed {n} records");Ok(())},"synthetic"=>{let count=val(&a,"--count","1000").parse().map_err(|_|"invalid --count")?;synthetic(count,&PathBuf::from(val(&a,"--output","synthetic.jsonl")),val(&a,"--seed","42").parse().unwrap())},"download"=>{let lang=val(&a,"--dataset","hindi");let(out_repo,out_path) = match lang.as_str(){"hindi"=>("HuggingFaceFW/fineweb-2","data/hin_Deva/train"),"english"=>("HuggingFaceFW/fineweb","data/100BT"),"openthoughts"=>("open-thoughts/OpenThoughts3-1.2M","data"),_=>return Err("dataset must be hindi, english, or openthoughts".into())};download(out_repo,out_path,&PathBuf::from(val(&a,"--output","./datasets")))},_=>{println!("smaul-dataset <filter|stream|synthetic|download> [options]");println!("filter: JSONL stdin -> filtered JSONL stdout");println!("stream: --input FILE [--min-chars N --max-chars N --max-records N]");println!("synthetic: --count N --output FILE [--seed N]");println!("download: --dataset hindi|english|openthoughts --output DIR");Ok(())}}
}
